mapper.select:
	 SELECT
	sum(count) 
FROM
	( SELECT count( 1 ) count FROM RSK_VALTBL_ASSET_SUB 


		   AND	PTL_ID = #{ptlId,jdbcType=VARCHAR}


		   AND  VAL_DATE = TO_DATE(#{valDate},'YYYY-MM-DD')


	UNION ALL SELECT count( 1 ) count FROM RSK_VALTBL_SUM_ASSET_SUB 


		   AND	PTL_ID = #{ptlId,jdbcType=VARCHAR}


		   AND  VAL_DATE = TO_DATE(#{valDate},'YYYY-MM-DD')


	)
